mapper.select:
select * FROM role where `status`!=2
and (name like concat('%',#{filterVal},'%') or created_user like concat('%',#{filterVal},'%')
or id = #{orId}
)
order by created_time desc

select count(1) FROM role where `status`!=2
and (name like concat('%',#{filterVal},'%') or created_user like concat('%',#{filterVal},'%')
or id = #{id}
)

select p.*, a.name as app_name, if(p2.cou is null or p2.cou=0,0,1) as is_child FROM `role` r join roles_permission rp on r.id = rp.role_id join permission p on p.pid=0 and rp.permission_id =p.id and p.status=1 join application a on r.app_id = a.id left join ( select p1.pid, count(1) as cou FROM permission p1 where p1.status=1 group by p1.pid ) p2 on p.id = p2.pid where r.id=#{roleId}
and (p.name like concat('%',#{filterVal},'%') or p.sign like concat('%',#{filterVal},'%') )
order by p.created_time desc

select r.* FROM role r left join depts_roles dr on r.id = dr.role_id left join dept d on dr.dept_id = d.id and d.status = 1 where r.`status`= #{status}
and r.app_id = #{appId}
and (r.name like concat('%',#{filterVal},'%') or r.created_user like concat('%',#{filterVal},'%') )
order by r.created_time desc

select a.* from ( select p.*, a.name as app_name FROM `role` r join roles_permission rp on r.id = rp.role_id join permission p on rp.permission_id =p.id and p.status=1 join application a on r.app_id = a.id where r.id=#{roleId}
and (p.name like concat('%',#{filterVal},'%') or p.sign like concat('%',#{filterVal},'%') )
union select p.*, a.name as app_name FROM `role` r join roles_permission_draft rp on r.id = rp.role_id join permission p on rp.permission_id =p.id and p.status=1 join application a on r.app_id = a.id where r.id=#{roleId}
and (p.name like concat('%',#{filterVal},'%') or p.sign like concat('%',#{filterVal},'%') )
)a order by a.pid desc
